-- 栈基础：数组和 top 约定组成的顺序栈。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '顺序栈','顺序栈用连续数组和 top 变量维护有效区间；top 的含义与判空、判满公式必须一致。',course.id,parent.id,'cs408-sequential-stack','AISTU',1,'REVIEWED',2,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-sequential-stack' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-sequential-stack',1,'REVIEWED','顺序栈',JSON_OBJECT('summary','顺序栈使用连续数组和 top 变量维护有效区间。top 可表示栈顶下标（空栈常为 -1），也可表示下一空位（空栈常为 0）；两种约定都正确，但判空、判满与 push/pop 的更新顺序不能混用。','steps',JSON_ARRAY('数组连续保存栈中元素','先明确 top 指向栈顶还是下一空位','push 前检查上溢并按约定更新 top','pop 前检查下溢并按约定读取或更新 top','判空和判满公式必须与 top 含义一致'),'prerequisite',JSON_OBJECT('contentKey','cs408-stack-lifo','title','栈的 LIFO 语义与基本操作','description','先确认所有更新都只发生在栈顶。'),'nextStep',JSON_OBJECT('contentKey','cs408-linked-stack','title','链栈','description','继续比较以单链表表头作为栈顶的实现。')),JSON_OBJECT('id','sequential-stack-v1','prompt','顺序栈中 top 表示“栈顶下标”还是“下一空位”时，最重要的要求是什么？','options',JSON_ARRAY(JSON_OBJECT('id','KEEP_CONVENTION','text','判空、判满和更新顺序必须与选定含义一致'),JSON_OBJECT('id','ALWAYS_MINUS_ONE','text','无论约定如何，空栈都必须令 top=-1')),'correctOptionId','KEEP_CONVENTION','correctExplanation','正确：两种 top 约定都可行，错误来自把不同约定的公式混在一起。','incorrectExplanation','不正确：top=-1 只是一种常用约定，不是所有顺序栈的唯一规则。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-sequential-stack' AND existing.content_version=1 WHERE point.content_key='cs408-sequential-stack' AND existing.id IS NULL;
